"""OAL synthetic eligibility audit v1.1. Preparer: Perplexity. Not an adjudicator."""
import copy,itertools,json,csv
from pathlib import Path

def neutral_assessment(case,ignore_conflict=False,ignore_substrate=False):
    reasons=[]
    for reviewer in case.get('reviewers',[]):
        conflict=reviewer['benefits_from_outcome'] or reviewer['reports_to_respondent']
        overlap=set(reviewer['substrates']) & set(case['disputed_substrates'])
        dependent=bool(overlap) and not reviewer['independent_corroboration']
        if (not conflict or ignore_conflict) and (not dependent or ignore_substrate):
            return True,reviewer['id']
        reasons.append(reviewer['id']+':'+('conflict' if conflict else 'dependent_evidence'))
    return False,';'.join(reasons) or 'no_reviewer'

def assess(case,mutation=None):
    x=copy.deepcopy(case)
    if mutation=='ignore_evidence': x['evidence']='sufficient'
    if mutation=='ignore_jurisdiction': x['jurisdiction']='established'
    if mutation=='ignore_method': x['method']='safe'
    if mutation=='ignore_review': x['review_available']=True
    neutral,trace=neutral_assessment(x,mutation=='ignore_conflict',mutation=='ignore_substrate')
    if x['identity']=='contradicted' or x['evidence']=='forged': result='REJECT_BASIS'
    elif x['current_ground']=='absent': result='CORRECT_ORDER' if x['order_active'] else 'NO_CUSTODY_GROUND'
    elif x['identity']!='clear' or x['evidence']!='sufficient': result='INDETERMINATE_EVIDENCE'
    elif x['jurisdiction']!='established': result='INDETERMINATE_JURISDICTION'
    elif not neutral: result='INDETERMINATE_EVALUATOR'
    elif x['method']=='unsafe': result='REJECT_METHOD'
    elif x['method']!='safe': result='INDETERMINATE_METHOD'
    elif x['alternative_available']: result='USE_ALTERNATIVE'
    elif x['review_available'] is not True: result='INDETERMINATE_REVIEW'
    elif x['current_ground']=='unknown': result='INDETERMINATE_GROUND'
    elif x['intent']=='involuntary': result='PROTECTIVE_REVIEW_CANDIDATE'
    else: result='INTERVENTION_REVIEW_CANDIDATE'
    research='END_PARTICIPATION' if x['consent']=='withdrawn' else ('SEPARATE_RESEARCH_REVIEW_REQUIRED' if x['consent']=='given' else 'NO_RESEARCH_AUTHORIZATION')
    return {'disposition':result,'research':research,'evaluator_trace':trace,'sentence':'NOT_DETERMINED'}

