MUTANTS=['ignore_evidence', 'ignore_jurisdiction', 'ignore_conflict', 'ignore_substrate', 'ignore_method', 'ignore_review']
if __name__=='__main__':
    rows=[]
    for c in CASES:
        r=assess(c)
        assert r['disposition']==c['expected'],c['id']
        rows.append(dict(case_id=c['id'],expected=c['expected'],**r))
    with Path('reproduced_audit.csv').open('w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    changed={m:sum(assess(c,m)['disposition']!=assess(c)['disposition'] for c in CASES) for m in MUTANTS}
    assert all(v>0 for v in changed.values())
    count=violations=0
    for ev,jur,ident,met,conf,dep,alt,rev in itertools.product(['sufficient','incomplete','forged'],['established','contested','absent'],['clear','uncertain','contradicted'],['safe','unsafe','unknown'],[False,True],[False,True],[False,True],[False,True]):
        x=copy.deepcopy(CASES[0]);x.update(evidence=ev,jurisdiction=jur,identity=ident,method=met,alternative_available=alt,review_available=rev)
        x['reviewers'][0]['benefits_from_outcome']=conf;x['reviewers'][0]['substrates']=['legacy_root'] if dep else ['independent_archive']
        candidate=assess(x)['disposition'].endswith('_CANDIDATE');count+=1
        violations+=int(candidate and not(ev=='sufficient' and jur=='established' and ident=='clear' and met=='safe' and not conf and not dep and not alt and rev))
    assert violations==0
    Path('reproduced_summary.json').write_text(json.dumps(dict(fixtures=len(CASES),mutation_changes=changed,enumerated_states=count,candidate_gate_violations=violations),indent=2))
